            "LEVEL_CNT": 2,
            "custom": "checkbox"
        }
    ];
    dataList_menu.setJSON(jsonArr);
    var sJSON = dataList_menu.getAllJSON();
    for (var i = 0; i < sJSON.length; i++) {
        var getInputType = dataList_menu.getCellData(i, "custom");
        var returnInfo = {};
        returnInfo.options = {
            displayFormat: ""
        };
        returnInfo.inputType = getInputType
        if (getInputType == "checkbox") {
            returnInfo.options.checkboxLabel = "에"
        } else if (getInputType == "select") {
            returnInfo.options.viewType = "icon";
            returnInfo.options.displayMode = "label";
            returnInfo.options.chooseOption = "true";
            returnInfo.options.chooseOptionLabel = "선택";
            returnInfo.itemSet = {
                label: "data",
                value: "code",
                nodeset: "data:ds_Temp1"
            }
        }
        gridView1.setCellInputType(i, "temp", returnInfo)
    }
};
